"""Convert legacy Qwen3-ASR Hub layouts to Transformers-native ``*-hf`` layout.

Legacy Hub packs store weights under ``thinker.*`` and nest config in
``thinker_config``. Transformers-native ``*-hf`` expects ``model.*`` keys and
flat ``text_config`` / ``audio_config``. Sidecars are preferably copied from an
official ``*-hf`` template; when Hub is unreachable we still remap weights and
flatten config offline (ForcedAligner must do this or every decode fails with
``Audio features and audio tokens do not match`` from random init dims).
"""

from __future__ import annotations

import json
import logging
import re
import shutil
import tempfile
from pathlib import Path
from typing import Any

_log = logging.getLogger("transub_engine.asr.qwen3_hf_convert")

# Sidecars that differ between qwen-asr layout and Transformers-native -hf.
_HF_SIDECAR_NAMES = (
    "config.json",
    "generation_config.json",
    "processor_config.json",
    "tokenizer.json",
    "tokenizer_config.json",
    "chat_template.jinja",
    "preprocessor_config.json",
)

_LEGACY_ONLY_NAMES = (
    "chat_template.json",
    "merges.txt",
    "vocab.json",
    "added_tokens.json",
    "special_tokens_map.json",
)

_DEFAULT_ASR_TEMPLATE = "Qwen/Qwen3-ASR-1.7B-hf"
_DEFAULT_ALIGN_TEMPLATE = "Qwen/Qwen3-ForcedAligner-0.6B-hf"

