# ForcedAligner needs two ``<timestamp>`` slots per word. Hub jinja joins with
# ASCII spaces (BPE id 220), which never match ``timestamp_token_id`` (151705).
_FORCED_ALIGNER_CHAT_TEMPLATE = """\
{%- set ns = namespace(audio_tokens='', words=[]) -%}
{%- for m in messages -%}
{%- if m.content is not string -%}
{%- for c in m.content -%}
{%- if c.type == 'audio' or ('audio' in c) or ('audio_url' in c) -%}
{%- set ns.audio_tokens = ns.audio_tokens + '<|audio_start|><|audio_pad|><|audio_end|>' -%}
{%- endif -%}
{%- if c.type == 'text' and (c.text is defined) -%}
{%- set ns.words = ns.words + [c.text] -%}
{%- endif -%}
{%- endfor -%}
{%- endif -%}
{%- endfor -%}
{{- ns.audio_tokens -}}
{%- for w in ns.words -%}{{ w }}<timestamp><timestamp>{%- endfor -%}
"""


# Hub / hybrid ForcedAligner packs sometimes ship WhisperFeatureExtractor
# sidecars. Whisper does not pad mel frames to ``2 * n_window`` → every
# ForcedAligner forward raises ``padded_feature_length … multiple of 100``.
_FORCED_ALIGNER_PREPROCESSOR = {
    "feature_extractor_type": "Qwen3ASRFeatureExtractor",
    "processor_class": "Qwen3ASRProcessor",
    "feature_size": 128,
    "sampling_rate": 16000,
    "padding_value": 0.0,
    "padding_side": "right",
    "return_attention_mask": True,
    "n_fft": 400,
    "hop_length": 160,
    "min_length": 8000,
    "chunk_length": 30,
    "n_samples": 480000,
    "nb_max_frames": 3000,
    "dither": 0.0,
    "n_window": 50,
}


def install_forced_aligner_chat_template(root: Path | str) -> dict[str, Any]:
    """Write a working ForcedAligner chat_template.jinja (offline, no Hub)."""
    path = Path(root)
    if not path.is_dir():
        return {"ok": False, "detail": "missing dir"}
    try:
        (path / "chat_template.jinja").write_text(
            _FORCED_ALIGNER_CHAT_TEMPLATE, encoding="utf-8"
        )
    except OSError as err:
        return {"ok": False, "detail": str(err)}
    legacy = path / "chat_template.json"
    if legacy.is_file():
        try:
            legacy.rename(path / "chat_template.json.legacy")
        except OSError:
            try:
                legacy.unlink()
            except OSError:
                pass
    return {"ok": True, "converted": True, "detail": "installed forced-aligner chat_template.jinja"}


def needs_forced_aligner_preprocessor_repair(root: Path | str) -> bool:
    """True when ForcedAligner preprocessor cannot pad mel to ``2 * n_window``."""
    path = Path(root)
    cfg = path / "preprocessor_config.json"
    if not cfg.is_file():
        return True
    try:
        data = json.loads(cfg.read_text(encoding="utf-8"))
    except Exception:
        return True
    if not isinstance(data, dict):
        return True
    fet = str(data.get("feature_extractor_type") or "").strip()
    if fet and fet != "Qwen3ASRFeatureExtractor":
        return True
    try:
        n_window = int(data.get("n_window") or 0)
    except (TypeError, ValueError):
        n_window = 0
    return n_window <= 0


def install_forced_aligner_preprocessor(root: Path | str) -> dict[str, Any]:
    """Write Qwen3ASRFeatureExtractor preprocessor (mel pad to ``2 * n_window``)."""
    path = Path(root)
    if not path.is_dir():
        return {"ok": False, "detail": "missing dir"}
    if not needs_forced_aligner_preprocessor_repair(path):
        return {"ok": True, "skipped": True, "detail": "preprocessor already Qwen3ASR"}
    out = path / "preprocessor_config.json"
    try:
        existing: dict[str, Any] = {}
        if out.is_file():
            try:
                raw = json.loads(out.read_text(encoding="utf-8"))
                if isinstance(raw, dict):
                    existing = raw
            except Exception:
                existing = {}
        merged = {**existing, **_FORCED_ALIGNER_PREPROCESSOR}
        out.write_text(
            json.dumps(merged, indent=2, ensure_ascii=False) + "\n",
            encoding="utf-8",
        )
    except OSError as err:
        return {"ok": False, "detail": str(err)}
    return {
        "ok": True,
        "converted": True,
        "detail": "installed Qwen3ASRFeatureExtractor preprocessor_config.json",
    }


def install_forced_aligner_sidecars(root: Path | str) -> dict[str, Any]:
    """Install ForcedAligner chat template + Qwen3ASR preprocessor offline."""
    tmpl = install_forced_aligner_chat_template(root)
    prep = install_forced_aligner_preprocessor(root)
    ok = bool(tmpl.get("ok")) and bool(prep.get("ok"))
    converted = bool(tmpl.get("converted") or prep.get("converted"))
    return {
        "ok": ok,
        "converted": converted,
        "detail": f"chat_template={tmpl.get('detail')}; preprocessor={prep.get('detail')}",
        "chat_template": tmpl,
        "preprocessor": prep,
    }


def looks_like_hf_layout(root: Path | str) -> bool:
    """True when layout supports Transformers-native ``continue_final_message``.

    Official ``*-hf`` ports ship ``chat_template.jinja``. Hybrid checkpoints that
    keep legacy ``chat_template.json`` (only ``add_generation_prompt``) break
    ``apply_transcription_request`` language prefills — treat those as incomplete.
    """
    path = Path(root)
    if not path.is_dir():
        return False
    if not (path / "config.json").is_file():
        return False
    has_tok = (path / "tokenizer.json").is_file()
    has_jinja = (path / "chat_template.jinja").is_file()
    legacy_tmpl = (path / "chat_template.json").is_file() or (path / "merges.txt").is_file()
    if has_jinja and has_tok:
        return True
    if has_jinja and (path / "processor_config.json").is_file():
        return True
    # tokenizer.json alone is ok only when no legacy chat/merges sidecars remain.
    if has_tok and not legacy_tmpl:
        return True
    return False


def looks_like_legacy_qwen_layout(root: Path | str) -> bool:
    path = Path(root)
    if not path.is_dir() or not (path / "config.json").is_file():
        return False
    if looks_like_hf_layout(path):
        return False
    return (path / "merges.txt").is_file() or (path / "chat_template.json").is_file()


def needs_hf_sidecar_repair(root: Path | str) -> bool:
    """Weights present but chat/tokenizer sidecars still legacy / hybrid."""
    path = Path(root)
    return _weight_present(path) and not looks_like_hf_layout(path)


_SHARD_OF_RE = re.compile(r"^model-(\d+)-of-(\d+)\.safetensors$", re.I)


def _weight_file_ok(path: Path, *, min_size: int = 1024) -> bool:
    try:
        return path.is_file() and path.stat().st_size > min_size
    except OSError:
        return False


def expected_safetensors_shards(root: Path | str) -> list[str]:
    """Filenames that must exist for a sharded safetensors snapshot."""
    path = Path(root)
    index = path / "model.safetensors.index.json"
    if index.is_file():
        try:
            data = json.loads(index.read_text(encoding="utf-8"))
        except Exception:
            return []
        names = sorted(
            {
                str(v).replace("\\", "/").rsplit("/", 1)[-1].strip()
                for v in (data.get("weight_map") or {}).values()
                if str(v).strip()
            }
        )
        return names
    found: list[tuple[int, int, str]] = []
    try:
        for p in path.glob("model-*.safetensors"):
            match = _SHARD_OF_RE.match(p.name)
            if match:
                found.append((int(match.group(1)), int(match.group(2)), p.name))
    except OSError:
        return []
    if not found:
        try:
            return [p.name for p in path.glob("model-*.safetensors") if _weight_file_ok(p)]
        except OSError:
            return []
    total = max(t for _, t, _ in found)
    sample = found[0][2]
    match = _SHARD_OF_RE.match(sample)
    idx_width = len(match.group(1)) if match else 5
    tot_width = len(match.group(2)) if match else 5
    return [
        f"model-{i:0{idx_width}d}-of-{total:0{tot_width}d}.safetensors"
        for i in range(1, total + 1)
    ]


def missing_safetensors_shards(root: Path | str) -> list[str]:
    """Shard filenames listed by the index / of-N pattern that are missing or tiny."""
    path = Path(root)
    return [name for name in expected_safetensors_shards(path) if not _weight_file_ok(path / name)]


def _weight_present(root: Path) -> bool:
    """True when a full weight file or a complete sharded safetensors set is on disk.

    ``model.safetensors.index.json`` alone is not enough — Hub can finish the
    JSON + most shards and still skip one LFS blob (seen as missing
    ``model-00004-of-00006.safetensors``).
    """
    path = Path(root)
    if _weight_file_ok(path / "model.safetensors"):
        return True
    if _weight_file_ok(path / "pytorch_model.bin"):
        return True
    expected = expected_safetensors_shards(path)
    if not expected:
        return False
    return not missing_safetensors_shards(path)


def template_hub_for_model_id(model_id: str) -> str:
    mid = str(model_id or "").strip().lower()
    if "align" in mid:
        return _DEFAULT_ALIGN_TEMPLATE
    if "0.6" in mid:
        return "Qwen/Qwen3-ASR-0.6B-hf"
    return _DEFAULT_ASR_TEMPLATE


def _iter_safetensors_weight_files(root: Path) -> list[Path]:
    single = root / "model.safetensors"
    if _weight_file_ok(single):
        return [single]
    return [root / name for name in expected_safetensors_shards(root) if _weight_file_ok(root / name)]


def _peek_safetensors_keys(path: Path, *, limit: int = 8) -> list[str]:
    """Read tensor names only. Never open with PyTorch here: download SSE runs
    in a worker thread, and initializing Torch off the main thread can kill the
    engine right as a ~4GB weight finishes."""
    try:
        from safetensors import safe_open
    except Exception:
        return []
    # numpy first — metadata-only, no torch import.
    for framework in ("np", "numpy"):
        try:
            with safe_open(str(path), framework=framework) as handle:
                keys = list(handle.keys())
            return keys[: max(1, int(limit))]
        except Exception:
            continue
    return []


def weights_have_thinker_prefix(root: Path | str) -> bool:
    """True when on-disk safetensors still use legacy ``thinker.*`` keys."""
    path = Path(root)
    for weight in _iter_safetensors_weight_files(path):
        for key in _peek_safetensors_keys(weight, limit=16):
            if str(key).startswith("thinker."):
                return True
    return False


def rewrite_thinker_weight_key(key: str, *, token_classification: bool) -> str | None:
    """Map one legacy ``thinker.*`` key to Transformers-native ``model.*`` / ``score``.

    Same rewrite used by jaykwok-style galgame conversion reports:
    ``thinker.audio_tower.proj{1,2}`` → ``model.multi_modal_projector.linear_{1,2}``,
    ``thinker.model.*`` → ``model.language_model.*``.
    ForcedAligner classification head: ``thinker.lm_head`` → ``score``.
    """
    raw = str(key or "")
    if raw.startswith("thinker.audio_tower.proj1."):
        return "model.multi_modal_projector.linear_1." + raw[len("thinker.audio_tower.proj1.") :]
    if raw.startswith("thinker.audio_tower.proj2."):
        return "model.multi_modal_projector.linear_2." + raw[len("thinker.audio_tower.proj2.") :]
    if raw.startswith("thinker.audio_tower."):
        return "model.audio_tower." + raw[len("thinker.audio_tower.") :]
    if raw.startswith("thinker.model."):
        return "model.language_model." + raw[len("thinker.model.") :]
    if raw == "thinker.lm_head.weight":
        return "score.weight" if token_classification else "lm_head.weight"
    if raw.startswith("thinker.lm_head."):
        suffix = raw[len("thinker.lm_head.") :]
        return f"score.{suffix}" if token_classification else f"lm_head.{suffix}"
    if raw.startswith("model.") or raw.startswith("score.") or raw.startswith("lm_head."):
        return raw
    return None


def _config_wants_token_classification(root: Path) -> bool:
    cfg_path = root / "config.json"
    if not cfg_path.is_file():
        return "align" in root.name.lower()
    try:
        data = json.loads(cfg_path.read_text(encoding="utf-8"))
    except Exception:
        return "align" in root.name.lower()
    if not isinstance(data, dict):
        return "align" in root.name.lower()
    arches = data.get("architectures") or []
    if any("TokenClassification" in str(a) for a in arches):
        return True
    thinker = data.get("thinker_config") if isinstance(data.get("thinker_config"), dict) else {}
    if int(thinker.get("classify_num") or 0) > 0:
        return True
    if int(data.get("classify_num") or 0) > 0:
        return True
    return "align" in root.name.lower()


def rewrite_legacy_thinker_weights(root: Path | str) -> dict[str, Any]:
    """Rewrite on-disk safetensors from ``thinker.*`` to ``model.*`` (in place)."""
    path = Path(root)
    files = _iter_safetensors_weight_files(path)
    if not files:
        return {"ok": False, "detail": "no safetensors weights"}
    if not weights_have_thinker_prefix(path):
        return {"ok": True, "skipped": True, "detail": "weights already model.*"}

    try:
        from safetensors import safe_open
        from safetensors.torch import save_file
    except Exception as err:
        return {"ok": False, "detail": f"safetensors unavailable: {err}"}

    token_classification = _config_wants_token_classification(path)
    rewritten = 0
    dropped = 0
    key_map: dict[str, str] = {}

    for weight_path in files:
        tensors: dict[str, Any] = {}
        with safe_open(str(weight_path), framework="pt") as handle:
            for key in handle.keys():
                new_key = rewrite_thinker_weight_key(
                    key, token_classification=token_classification
                )
                if not new_key:
                    dropped += 1
                    continue
                if new_key in tensors:
                    return {
                        "ok": False,
                        "detail": f"duplicate key after rewrite: {new_key}",
                    }
                tensors[new_key] = handle.get_tensor(key)
                key_map[key] = new_key
                rewritten += 1
        tmp_fd, tmp_name = tempfile.mkstemp(
            prefix=weight_path.stem + ".",
            suffix=".safetensors.tmp",
            dir=str(weight_path.parent),
        )
        import os

        os.close(tmp_fd)
        tmp_path = Path(tmp_name)
        try:
            save_file(tensors, str(tmp_path))
            tmp_path.replace(weight_path)
        except Exception:
            try:
                tmp_path.unlink(missing_ok=True)
            except OSError:
                pass
            raise

    index_path = path / "model.safetensors.index.json"
    if index_path.is_file() and key_map:
        try:
            index = json.loads(index_path.read_text(encoding="utf-8"))
            weight_map = index.get("weight_map")
            if isinstance(weight_map, dict):
                index["weight_map"] = {
                    key_map.get(str(k), str(k)): v for k, v in weight_map.items()
                }
                index_path.write_text(
                    json.dumps(index, ensure_ascii=False, indent=2) + "\n",
                    encoding="utf-8",
                )
        except Exception as err:
            _log.warning("Could not rewrite safetensors index under %s: %s", path, err)

    _log.info(
        "Rewrote legacy thinker.* weights under %s (tensors=%d dropped=%d token_cls=%s)",
        path,
        rewritten,
        dropped,
        token_classification,
    )
    return {
        "ok": True,
        "converted": True,
        "detail": f"rewrote {rewritten} tensors",
        "rewritten": rewritten,
        "dropped": dropped,
        "token_classification": token_classification,
    }


def _slim_sub_config(raw: Any, keep: frozenset[str], *, default_model_type: str) -> dict[str, Any]:
    src = raw if isinstance(raw, dict) else {}
    out = {k: v for k, v in src.items() if k in keep and v is not None}
    out.setdefault("model_type", src.get("model_type") or default_model_type)
    return out


def flatten_thinker_config_offline(root: Path | str) -> dict[str, Any]:
    """Rewrite ``config.json`` from nested ``thinker_config`` to flat HF layout."""
    path = Path(root)
    cfg_path = path / "config.json"
    if not cfg_path.is_file():
        return {"ok": False, "detail": "missing config.json"}
    try:
        data = json.loads(cfg_path.read_text(encoding="utf-8"))
    except Exception as err:
        return {"ok": False, "detail": f"bad config.json: {err}"}
    if not isinstance(data, dict):
        return {"ok": False, "detail": "config.json is not an object"}
    if isinstance(data.get("text_config"), dict) and isinstance(data.get("audio_config"), dict):
        if not isinstance(data.get("thinker_config"), dict):
            return {"ok": True, "skipped": True, "detail": "config already flat"}

    thinker = data.get("thinker_config") if isinstance(data.get("thinker_config"), dict) else {}
    if not thinker and not (data.get("text_config") and data.get("audio_config")):
        return {"ok": False, "detail": "no thinker_config / flat configs to flatten"}

    text_src = thinker.get("text_config") if isinstance(thinker.get("text_config"), dict) else data.get("text_config")
    audio_src = (
        thinker.get("audio_config") if isinstance(thinker.get("audio_config"), dict) else data.get("audio_config")
    )
    text_config = _slim_sub_config(text_src, _TEXT_CONFIG_KEEP, default_model_type="qwen3")
    audio_config = _slim_sub_config(
        audio_src, _AUDIO_CONFIG_KEEP, default_model_type="qwen3_asr_encoder"
    )
    # Legacy packs use ``qwen3_asr_audio_encoder``; Transformers registers ``qwen3_asr_encoder``.
    audio_mt = str(audio_config.get("model_type") or "")
    if audio_mt in ("qwen3_asr_audio_encoder", "qwen3_asr_audioencoder"):
        audio_config["model_type"] = "qwen3_asr_encoder"
    # Encoder configs in the wild sometimes use max_source_positions; HF uses both.
    if "max_source_positions" in audio_config and "max_position_embeddings" not in audio_config:
        audio_config["max_position_embeddings"] = audio_config["max_source_positions"]

    classify_num = int(thinker.get("classify_num") or data.get("classify_num") or 0)
    token_classification = classify_num > 0 or _config_wants_token_classification(path)
    if token_classification and classify_num <= 0:
        classify_num = 5000

    flat: dict[str, Any] = {
        "architectures": (
            ["Qwen3ASRForTokenClassification"]
            if token_classification
            else ["Qwen3ASRForConditionalGeneration"]
        ),
        "model_type": "qwen3_asr",
        "audio_config": audio_config,
        "text_config": text_config,
        "audio_token_id": int(
            thinker.get("audio_token_id")
            or data.get("audio_token_id")
            or 151676
        ),
        "timestamp_token_id": int(data.get("timestamp_token_id") or 151705),
        "initializer_range": float(
            thinker.get("initializer_range") or data.get("initializer_range") or 0.02
        ),
        "tie_word_embeddings": bool(text_config.get("tie_word_embeddings", True)),
        "token_classification_bias": bool(data.get("token_classification_bias", False)),
        "transformers_version": data.get("transformers_version") or "4.57.0",
    }
    if data.get("timestamp_segment_time") is not None:
        flat["timestamp_segment_time"] = data.get("timestamp_segment_time")
    if data.get("support_languages") is not None:
        flat["support_languages"] = data.get("support_languages")
    if data.get("dtype") is not None:
        flat["dtype"] = data.get("dtype")
    elif thinker.get("dtype") is not None:
        flat["dtype"] = thinker.get("dtype")
    eos = data.get("eos_token_id") or text_config.get("eos_token_id") or (151643, 151645)
    flat["eos_token_id"] = eos
    pad = data.get("pad_token_id") or text_config.get("pad_token_id") or 151645
    flat["pad_token_id"] = pad

    if token_classification and classify_num > 0:
        flat["num_labels"] = classify_num
        flat["id2label"] = {str(i): f"LABEL_{i}" for i in range(classify_num)}
        flat["label2id"] = {f"LABEL_{i}": i for i in range(classify_num)}

    cfg_path.write_text(json.dumps(flat, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    _log.info(
        "Flattened thinker_config → HF config under %s (token_cls=%s labels=%s)",
        path,
        token_classification,
        classify_num if token_classification else 0,
    )
    return {
        "ok": True,
        "converted": True,
        "detail": "flattened thinker_config",
        "token_classification": token_classification,
        "classify_num": classify_num if token_classification else 0,
    }


def _fetch_template_sidecars(template_hub: str, cache_dir: Path) -> Path:
    """Download only non-weight files from ``template_hub`` into ``cache_dir``."""
    from huggingface_hub import snapshot_download

    cache_dir.mkdir(parents=True, exist_ok=True)
    ignore = [
        "*.safetensors",
        "*.bin",
        "*.pt",
        "*.pth",
        "*.onnx",
        "*.msgpack",
        "*.h5",
        "optimizer.pt",
        "scheduler.pt",
        "rng_state.pth",
        "trainer_state.json",
        "training_args.bin",
    ]
    snapshot_download(
        repo_id=template_hub,
        local_dir=str(cache_dir),
        ignore_patterns=ignore,
        max_workers=4,
    )
    return cache_dir


def convert_dir_to_hf_layout(
    dest: Path | str,
    *,
    template_hub: str | None = None,
    model_id: str | None = None,
    force: bool = False,
) -> dict[str, Any]:
    """Remap legacy thinker weights + refresh sidecars toward official ``*-hf``.

    Weight remap is mandatory when ``thinker.*`` keys are present (otherwise
    ForcedAligner loads as a randomly-initialized 1.7B-shaped shell and every
    align decode fails). Sidecar Hub fetch is best-effort; offline flatten of
    ``thinker_config`` keeps the model loadable without network.
    """
    root = Path(dest)
    if not root.is_dir():
        return {"ok": False, "detail": f"missing dir: {root}"}
    if not _weight_present(root):
        return {"ok": False, "detail": f"no weights under {root}"}

    weight_result: dict[str, Any] = {"ok": True, "skipped": True}
    if weights_have_thinker_prefix(root):
        weight_result = rewrite_legacy_thinker_weights(root)
        if not weight_result.get("ok"):
            return weight_result

    mid = str(model_id or root.name).strip().lower()
    template_result: dict[str, Any] | None = None
    if "align" in mid or _config_wants_token_classification(root):
        template_result = install_forced_aligner_sidecars(root)

    already_hf = looks_like_hf_layout(root) and not weights_have_thinker_prefix(root)
    if already_hf and not force:
        return {
            "ok": True,
            "skipped": True,
            "detail": "already -hf layout",
            "weights": weight_result,
            "chat_template": template_result,
        }

    hub = str(template_hub or template_hub_for_model_id(model_id or root.name)).strip()
    if not hub:
        hub = _DEFAULT_ASR_TEMPLATE

    cache = root / ".cache" / "hf-template" / hub.replace("/", "__")
    fetch_err: str | None = None
    copied = 0
    try:
        _fetch_template_sidecars(hub, cache)
        for name in _HF_SIDECAR_NAMES:
            src = cache / name
            if not src.is_file():
                continue
            shutil.copy2(src, root / name)
            copied += 1
    except Exception as err:
        fetch_err = f"template fetch failed ({hub}): {err}"

    removed = 0
    flat_result: dict[str, Any] | None = None
    if fetch_err:
        # Offline path: flatten config so AutoConfig no longer invents 2048/3584 defaults.
        flat_result = flatten_thinker_config_offline(root)
        if not flat_result.get("ok") and not flat_result.get("skipped"):
            return {
                "ok": False,
                "detail": fetch_err,
                "weights": weight_result,
                "offline_config": flat_result,
            }
    else:
        for name in _LEGACY_ONLY_NAMES:
            legacy = root / name
            if legacy.is_file():
                try:
                    legacy.unlink()
                    removed += 1
                except OSError:
                    pass
        # Hub's ForcedAligner jinja joins with spaces (no ``<timestamp>`` tokens).
        # Re-install our working template + Qwen3ASR preprocessor after sidecar copy.
        if "align" in mid or _config_wants_token_classification(root):
            template_result = install_forced_aligner_sidecars(root)

    if weights_have_thinker_prefix(root):
        return {
            "ok": False,
            "detail": "thinker.* weights remain after rewrite",
            "weights": weight_result,
        }

    # Sidecars may still be legacy (no jinja) when Hub is down — weights+config are enough to load.
    if not looks_like_hf_layout(root) and not fetch_err:
        return {
            "ok": False,
            "detail": (
                f"conversion incomplete under {root} "
                f"(copied={copied}, removed={removed}, template={hub})"
            ),
            "weights": weight_result,
        }

    detail = (
        f"converted via {hub}"
        if not fetch_err
        else f"weights remapped; offline config ({fetch_err})"
    )
    _log.info(
        "Qwen3-ASR converted toward -hf layout: %s (%s, sidecars=%d, removed=%d)",
        root,
        detail,
        copied,
        removed,
    )
    return {
        "ok": True,
        "converted": True,
        "detail": detail,
        "copied": copied,
        "removed": removed,
        "weights": weight_result,
        "offline_config": flat_result,
        "chat_template": template_result,
        "fetch_error": fetch_err,
    }


def ensure_qwen3_hf_checkpoint(root: Path | str, *, model_id: str | None = None) -> dict[str, Any]:
    """Ensure weights/config are Transformers-loadable before ``from_pretrained``."""
    path = Path(root)
    mid = str(model_id or path.name).strip().lower()
    is_aligner = "align" in mid or _config_wants_token_classification(path)
    needs_weights = weights_have_thinker_prefix(path)
    needs_sidecars = needs_hf_sidecar_repair(path)
    needs_aligner_template = is_aligner and not (path / "chat_template.jinja").is_file()
    needs_aligner_preprocessor = is_aligner and needs_forced_aligner_preprocessor_repair(path)
    cfg_needs_flatten = False
    cfg_path = path / "config.json"
    if cfg_path.is_file():
        try:
            data = json.loads(cfg_path.read_text(encoding="utf-8"))
            cfg_needs_flatten = isinstance(data, dict) and isinstance(
                data.get("thinker_config"), dict
            ) and not (
                isinstance(data.get("text_config"), dict)
                and isinstance(data.get("audio_config"), dict)
            )
        except Exception:
            cfg_needs_flatten = False
    if (
        (needs_aligner_template or needs_aligner_preprocessor)
        and not (needs_weights or needs_sidecars or cfg_needs_flatten)
    ):
        return install_forced_aligner_sidecars(path)
    if not needs_weights and not needs_sidecars and not cfg_needs_flatten:
        return {"ok": True, "skipped": True, "detail": "checkpoint ready"}
    return convert_dir_to_hf_layout(
        path,
        template_hub=template_hub_for_model_id(mid or path.name),
        model_id=mid or path.name,
        force=True,
    )


def maybe_convert_after_download(model_id: str, dest: Path | str) -> dict[str, Any]:
    """One-liner hook for download.py — convert / repair sidecars after Hub pull."""
    mid = str(model_id or "").strip()
    root = Path(dest)
    if mid in CONVERT_AFTER_DOWNLOAD_IDS:
        return convert_dir_to_hf_layout(
            root,
            template_hub=template_hub_for_model_id(mid),
            model_id=mid,
            force=False,
        )
    needs_repair = needs_hf_sidecar_repair(root)
    # Complete *-hf snapshots must not peek 4GB weights just to confirm keys.
    if mid in REPAIR_AFTER_DOWNLOAD_IDS and not needs_repair:
        return {"ok": True, "skipped": True, "detail": "no convert needed"}
    if needs_repair or weights_have_thinker_prefix(root):
        return convert_dir_to_hf_layout(
            root,
            template_hub=template_hub_for_model_id(mid or root.name),
            model_id=mid or root.name,
            force=True,
        )
    return {"ok": True, "skipped": True, "detail": "no convert needed"}
